{
  "technical_and_design_decisions": [
    "U1: Implement a per-transaction context object passed into contract method invocations to ensure thread-safety in Java/Node contract APIs, giving access to ChaincodeStub and ClientIdentity.",
    "U2/U3: Refactor the Go package structure by moving 'protos/utils' to 'protoutils' and updating all internal and external import paths across the codebase.",
    "U4: Backport the existing Kafka health check library and handler registration from the master branch to the v1.4 LTS release branch, maintaining backward compatibility.",
    "U5: Extend the peer proposal endorsement access control to allow Channel Readers to invoke chaincode proposals if the simulation result contains no ledger state modifications (write sets are empty).",
    "U6: Introduce a new configuration property ('peer.discovery.externalEndpoint') distinct from 'peer.gossip.externalEndpoint' to allow independent configuration of advertised endpoints in Service Discovery.",
    "U7: Add a REST '/version' endpoint to the Operations service present in both peer and orderer processes to expose build and release version information.",
    "U8: Audit and refactor Go chaincode and SDK sample code to adhere to idiomatic Golang standards, error handling patterns, and formatting guidelines."
  ],
  "assumptions": [
    "U2 and U3 are duplicate requirements in the specification and represent a single refactoring task.",
    "Development and testing environments have access to Docker container networks and Kafka cluster mocks for integration testing.",
    "The codebase relies on standard Go build tools and Hyperledger Fabric integration test framework (Behave/E2E tests).",
    "All effort estimates assume implementation, unit testing, and integration verification are performed by a single experienced developer."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Implement Contract Transactional Context (U1)",
      "activity_description": "Design and implement per-transaction context handling for contract APIs, allowing developers thread-safe access to the chaincode stub and client identity during execution.",
      "most_likely_effort": 18
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Refactor Protos Utils to Protoutils (U2/U3)",
      "activity_description": "Relocate the protos/utils package to protoutils, update all package references across core modules, and ensure proto helper functions remain backward compatible.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Backport Kafka Health Checks to 1.4 LTS (U4)",
      "activity_description": "Cherry-pick and adapt Kafka health check monitoring logic from master to 1.4 LTS branch, resolve merge conflicts, and verify health checker endpoint integration.",
      "most_likely_effort": 14
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Implement Read-Only Invocation Access for Readers (U5)",
      "activity_description": "Update access control checks on peer proposal processing to allow channel Reader permissions when proposals perform read-only state operations.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Add Advertised External Endpoint for Service Discovery (U6)",
      "activity_description": "Add the 'peer.discovery.externalEndpoint' configuration parameter, update service discovery endpoint resolver logic, and update configuration documentation.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Expose Version Endpoint in Operations Service (U7)",
      "activity_description": "Implement the HTTP REST endpoint '/version' within the Operations service for both peer and orderer binaries to return build version metadata.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Refactor Go Samples to Idiomatic Code (U8)",
      "activity_description": "Audit, clean up, and rewrite Golang sample chaincodes and helper scripts to follow idiomatic Go conventions, structure, and error handling.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Integration Testing and Quality Assurance",
      "activity_description": "Run unit tests, end-to-end service discovery tests, operations API checks, and verify cross-component stability after all changes.",
      "most_likely_effort": 16
    }
  ],
  "reported_total": {
    "most_likely_effort": 114
  }
}

